INSERT INTO stories (id, title, body, date, place, created_at) VALUES ('4e48757b-4884-49f6-8744-21cef891c441', 'A historic marriage', 'ازدواج تاريخى تقريباً در سالهاى ١٣٠٦ تا ١٣٠٨هجرى شمسى بود، شراكت محمد زهتاب، حسين، رمضان، قاسم دارابى واسداله جابريان ادامه داشت، مديريت شركت كم كم بدست رمضان دارابى سپرده شده بود، در اين موقع يكى از تجار قزوين كه بسيار محترم واز خانواده خوبى بود مشكل مالى پيدا كرده، كه در نتيجه بيشتر اموال خود را فروخته ومشكلات مالى را برطرف ساخت، ولى ديگر سرمايه اى براى ادامه كار نداشت، رمضان دارابى كه از وضعيت او با خبر شده بود از او دعوت كرد كه در شركت آنها مشغول فعاليت گردد، او نيز قبول كرد ودر شركت بعنوان ميرزا(حسابدار) مشغول بكار شد. ضمناً رمضان دارابى باو گفته بود كه انشاءاله هر وقت خواستيم براى قاسم زن بگيريم دختر شمارا خواهيم گرفت. او نيز از اين وعده بسيار خوشحال شده بود.در آن موقع حسين دارابى درگيرى واختلاف شديدى با حاج ميرزاآقامسعودى رئيس صنف قصاب داشت، اين درگيرى مدت زيادى بطول انجاميده بود.( البته رمضان وقاسم از اين درگيرى خسته شده وخواهان خاتمه آن بودند. ) روزى شخصى نزد رمضان رفته ومى گويد كه شما دوخانواده چقدر باهم در گير مى شويد، هر دو خانواده خوب وهردو آدمهاى فهميده، چرا باهم آشتى ورفاقت نمى كنيد؟ رمضان مى گويد من هم خسته شده ام ولى برادر ما كوتاه نمى آيد.آن مرد مى گويد براى شروع مى توانيد دختر حاج ميرزاآقا را براى قاسم بگيريد، رمضان مى گويد مگر حاج ميرزاآقا دختر دارد؟ او مى گويد بله، چند تا. رمضان بلا فاصله نزد همسرخود، همسر حسين وخواهرش فاطمه مى رود وبه آنها مى گويد فوراً شيرينى خريده وبه خانه حاج ميرزاآقا برويد وضمن آشتى كردن، دختر او را براى قاسم خواستگارى نمائيد. آنها هم كله قند وشيرينى خريده وبه منزل حاج ميرزاآقا مى روند. خانواده حاج ميرزاآقا هم از آنها استقبال وپذيرائى خوبى مى كنند، وبه خواستكارى آنها نيز پاسخ مثبت مى دهند. سر انجام دو خانواده كه سالها اختلاف شديد داشتند بخاطر اين ازدواج باهم رابطه خوبى پيدا كردند. رمضان دارابى زمان ازدواج راتعين وكارت دعوت آنرا نيز خريدارى نمود. او فراموش كرده بود كه قبلاً به منشى خود قولى براى دخترش داده بود. كارت ها را روى ميز ميرزا گذاشت، آن تاجر سابق وقتى كارتهارا ديد سئوال كرد اينها چى هستند؟ رمضان گفت دختر حاج ميرزاآقا را براى قاسم گرفته ايم، ناگهان آن مرد بيحال شد وبه زمين افتاد، چند نفر او را بلند كرده وپس از اينكه حالش را جا آوردند، رمضان پرسيد كه چى شد؟ او در حاليكه حالت افسرده اى داشت گفت شما كه قول داديد دختر مرا براى قاسم بگيريد! رمضان از وضعيت پيش آمده بسيار ناراحت شده واز اينكه دل آن پير مرد راشكسته از كار خود سخت عصبانى گرديد، وپس از چند دقيقه تفكر، مى گويد ناراحت نشويد دختر شمارا براى اسداله خواهرزاده ام مى گيرم، آنها كه با هم فرقى ندارند، آن مرد خوشحال شده وبلافاصله به خانواده اش اطلاع مى دهد. اسداله جابريان كه در كارخانه مشغول كار بود در آن زمان نوجوانى بيش نبود، وقتى از كارخانه برگشت به او مى گويندكه دو شب ديگر عروسى تو خواهد بود. او در حاليكه شوكه شده بودبه مادر وپدر خود اطلاع داده وآنها هم موافقت مى نمايند. لذا دريك شب دو ازدواج قاسم دارابى واسداله جابريان با همسرانشان انجام مى شود. رمضان دارابى كه به هر دو داماد ( برادر وخواهرزاده اش) علاقه زيادى داشت مى خواست جشن بزرگى برپا نمايد ولى در همسايگى آنها مرد روحانى بزرگى بنام حاجى مجتحد( شهيدى) زندگى مى كردكه با خانواده آنها نيز ارتباط ورفت آمد داشت وچون آن مردروحانى صداى موزيك را حرام مى دانست رمضان اجباراً احترام گذاشته واز چند نفر كه ويلن وتار مى زدند دعوت نمودوبه آنها سفارش كرد كه آهسته بنوازند. مجلس عروسى آغاز ومهمانان در حياط خانه مورد پذيرائى قرار گرفتند، ناگهان يكى از خدمتكاران نزد رمضان رفته ومى گويد كه حاجى مجتحد در كوچه سروصداكرده است. رمضان دارابى به كوچه رفته ومى بيند كه حاج آقا با عصبانيت قدم زده وبه آنها فحاشى مى كند، تعداد زيادى از مردم وهمسايه ها كه دعوت نداشتند نيز در اطراف حاج آقا ايستاده وتماشا ميكنند، او نزد حاج آقا رفته وبا احترام سلام كرده ومى گويد حاج آقا چى شده؟ حاج آقا مجدداً فحاشى كرده ومى گويد مطرب آورده ايد؟ او مى گويد بله ولى سفارش كرده ام آهسته بزنند كه مزاحم شما نشوند، حاج آقا مى گويد همين الان آنهارا بيرون كن. رمضان مى گويد، حاج آقا مهمان زياد داريم والان خوب نيست آنها را بيرون كنم لطفاً شما كوتاه بيائيدوبگذاريد اين مردم به خانه هايشان بروند. حاج آقا مجدداً فحش هاى ركيك مى دهد كه ناگهان رمضان عصبانى شده ومى گويد حاج آقا چهارديوارى، اختيارى به شما چه مربوط است شما اگرراست مى گوئيد جلو برادرانتان را بگيريد كه به خانه هاى فساد نروند. حاج آقا مى گويد دروغ مى گوئى! رمضان مى گويد همين الان آنها در آنجا هستند. او ميگويد بايد ثابت كنى! رمضان پاسخ مى دهدباشد، سپس او به نوكر خود مى گويد درويش فوراً با رمضان برو واگر نتوانست ثابت كند من امشب عروسى را بهم مى زنم. رمضان با درويش با درشگه شخصى حاج آقا به محله بد نام قزوين رفته ودر جلوى يكى از خانه ها توقف مى كنند. رمضان مى گويد درويش با من به داخل مى آئى يانه درويش مى گويد نه شما برو داخل. رمضان به داخل رفته ودر اطاقى در طبقه دوم كه پنجره اى نيز به كوچه داشت، برادران حاج آقارا مى بيند كه همگى در كنار زنان روسپى نشسته ومشغول خوردن مشروب مى باشند. سلام كرده ومى گويد من شما را به عروسى دعوت كردم چرا نيامديد. آنها گفتند حاج آقا آنجاست ما نمى توانيم بيائيم. رمضان مى گويد چراعمامه ها را در كنار سفره مشروب گذاشته ايد لااقل حرمت آنها را نگهداريد، سپس عمامه هاى آنها جمع كرده ودر يك دستمال ابريشمى بزرگ گذاشته ودستمال را روى طاقچه قرار مى دهد، سپس چند دقيقه نشسته ويك استكان مشروب با آنها خورده وخدا حافظى كرده وموقع خروج يواشكى دستمال عمامه ها رابرداشته وبه پائين مى رود. درويش كه صداى برادران حاج آقا را از پنجره اطاق شنيده بود وحالا هم عمامه هاى آنها را مى بيندمى گويد عمامه هارا نياور. رمضان گفت بايستى غير حاج آقا مردم محل هم بفهمند وبايد حاج آقا خجالت بكشد وديگر مزاحم همسايه ها نشود. آنگاه به جلوى خانه حاج آقا مى رسند، حاج أقا كه همچنان در كوچه قدم زده وفحاشى مى كرد. از درويش سئوال كرد ثابت شد كه او دروغ مى گويد، رمضان پاسخ مى دهد اينهم عمامه هايشان ودرويش نيز حرف اورا تائيد مى نمايد. حاج آقا از خجالت فوراً بداخل خانه اش رفت. رمضان به يكى از دوستان مى گويد اين عمامه ها را ببر فلان جا ودر طاقچه آن اطاق قرار بده بطورى كه آنها متوجه نشوند. سپس شخصى رابدنبال نوازنده شيپور سربازى فرستاد وچند نفر شيپورزن دعوت كرد وتمام مردم تماشاگر كوچه را نيز به عروسى دعوت كرده وبه همه مى گويد تا صبح با صداى بلند شيپوركه مى زنند شما هم شادمانى كنيد. آن شب براى اهل محل شب فراموش نشدنى بوده وحاجى مجتهدنيز از آن ببعد بى سرو صدا به خانه خود مى رفت وديگر مزاحم همسايه ها نمى شد.', '1927', 'Qazvin, Iran', '2026-08-27T07:56:09.237Z');
