INSERT INTO stories (id, title, body, date, place, created_at) VALUES ('92e9f21e-ff34-405a-b548-44af5dfa8b51', 'Hossein Zehtab (Darabi), fifth generation', 'حسين زهتاب (دارابى) نسل ٥ حسين زهتاب تقريباً درسال ١٢٦١ هجرى شمسى در قزوين متولد گرديد. او مردى باجثه كوچك، وبسيار فرز وزبردست ونيز مهربان ودوستار خانواده ومردم بود. در گذشته دربين بچه هاى محل رسم بر اين بود كه دائماًباهم دعواهاى محلى داشتند وافرادى ازاين بچه ها كه توانائى رهبرى داشتند را بعنوان رهبر گروه انتخاب مى كردند. او نيز چنين بود وهميشه رهبر وپيش كسوت دوستان قرار داشت، ودردعواها به تنهائى توانائى روبرو شدن باتعداد زيادى از جوانان راداشت وهمه آنها راشكست مى داد. او مهمان نواز بود وهمه اورا بعنوان آدم خير ودست ودلباز مى شناختند، ايشان از همسرش عاتقه خانم داراى سه فرزند بنام هاى غلامرضا، غلامحسين واكرم گرديد، غلامرضا در كودكى بعلت بيمارى فوت كرد و شناسنامه اورا براى غلامحسين اختصاص دادند ودرنتيجه غلامحسين بعداً بعنوان غلامرضا شناخته شد. زمانى او همراه گروهى از مردم قزوين براى زيارت كربلا به كشور عراق مسافرت نمود، وسيله مسافرت در آن زمان كجاوه، ارابه ويا اسب بود، در نتيجه مسافرت حدود سه الى چهار ماه طول مى كشيد، درآن موقع در ايران مرض طاعون شيوع داشت وكشور عراق نيز اجباراً آن مسافران رابمدت يك ماه تحت قرنطينه قرار داده ودر يك كاروانسرائى محبوس كرد. حسين كه درانتظارهرچه زودتر رسيدن به كربلابود، نمى توانست اين وضع را تحمل نمايد، لذا روزى باتوجه به اينكه ديوار بيرونى قلعه كاملاً به زمين عمود نبوده وحالت شيب داشت، او تصميم گرفت به طريقى از آنجا بگريزد وآجرى را با هر دو دست برداشته وطرف ديگر آنراروى ديوارقرارداده، به اين اميد كه تا پائين سُربخورد، خودرا در حضور همراهان مسافربه پائين پرت مى كند، متأسفانه او از ارتفاع پانزده مترى به زمين پرت شده وبيهوش ميگردد. مسافرانى كه اين صحنه را ديدند همگى فكر كردند كه او فوت كرد. مأموران عراقى نيز او را روى تخته اى انداخته وبردند. پس از چند روز مسافران آزاد شده وبه كربلا رفتند، سه ماه بعد مسافران مذكور برگشته ودر شهر تاكستان مورد استقبال مردم قرار گرفتند، خانواده حسين نيز براى استقبال از او در تاكستان جمع شده بودند، ولى حسين را نديدند وازمسافران شنيدند كه حسين فوت كرده است. آنها نيز مراسم ختم براى او برگذار نموده وهمگى عزادار شدند. پس از چهار ماه شخصى از تاكستان آمد وبه برادران حسين اطلاع داد كه حسين زهتاب در تاكستان منتظر شما است ، آنها كه اين موضوع را باور نداشتند گفتند حسين فوت كرده است. او چوب خيزرانى به آن ها داد وگفت اين چوب را حسين داده ، آنها باتوجه به اينكه چوب خيزران براى زهتاب ها علامتى مخصوصى بود، حرف اوراباوركرده وباعجله به تاكستان رفتند. در تاكستان حسين را زنده مشاهده نمودند، حسين مى گويد كه من سه ماه در بيمارستان بغداد بسترى بوده تاتمام شكستگى هايم بهبود يابدو نمى توانستم به شمااطلاع دهم ، آنگاه آنها بسيار خوشحال شده وجشن بزرگى برپا كردند. عاتقه خانم همسر حسين نيززنى خوب، مسلمان وبسيار مهربان وازخانواده خوبى بود. باتوجه به اينكه درگذشته رسم براين بود كه وقتى عروس به خانه داماد مى رفت، فاميل داماد نام اورا عوض مى كردند، اورا درخانه همسرش گلين خانم نام نهاده بودند. حسين درسال ١٣١٦ در سن پنجاه وپنج سالگى ودرحاليكه هنوز پدرش زنده بود بعلت بيمارى درگذشت. جالب توجه است كه او مدتى با مهدى زهتاب اختلاف شديدى داشت كه سرانجام دختر اورابراى برادرش رمضان گرفت ومدتى نيز با حاج ميرزا آقا مسعودى اختلاف داشت كه عاقبت دختر او نيز همسر قاسم برادر ديگرش گرديد.', NULL, 'Qazvin, Iran', '2026-08-27T07:56:09.237Z');
