INSERT INTO stories (id, title, body, date, place, created_at) VALUES ('b4ca36c1-68b5-4c63-9ad2-e225b381ba76', 'Ramazan Darabi, fifth generation', 'رمضان دارابى ( نسل پنجم ) رمضان داراى در سال ١٢٧٢ هجرى شمسى در قزوين متولد گرديد، او نيز مانند خواهرش فاطمه خانم قامتى بلند وبدنى ورزيده داشت، هوش زياد وسخنورى از محاسن او بشمار مى رفت، در سن ١٥ سالگى به شاگردى نزد يك تاجر بزرگ ارمنى بنام ميكائيل خان رفت وچندسالى درآنجا فعاليت كرده ورموز كار تجارت را فراگرفت. سپس در سن ١٨ سالگى بعنوان مشاور در خدمت آقاى مهدى زهتاب ( عاريه بند ها) قرار گرفت وچندسالى نيز با او همكارى نموده وكار روده وپوست را از او آموخت. سپس به همكارى با پدر وبرادرانش پرداخت، وچون تجربه زيادى در امور تجارت ومعاملات داشت در شراكتشان امور خريد وفروش رابعهده گرفت. هنگاميكه او نزد مهدى زهتاب بود به دختر او فرخنده دل بسته وعلاقه مند گرديده بود. ولى چون برادر بزرگش حسين با مهدى زهتاب اختلاف شديدى داشت اين موضوع را عنوان نكرده بود. از جانب ديگر پدر وبرادرش دائماً مى خواستند براى او همسر انتخاب نمايند ولى او زير بار نمى رفت، تاروزى حسين وهمسرش وهمسر پدرش او را محاصره كرده وتحت فشار قرار دادندكه چرا او زن نمى گيرد، او كه تحت فشار قرار مى گيرد مى گويد فرخنده را مى خواهد، حسين بلافاصله به همسر ومادرش مى گويد فوراً به منزل مهدى برويد وآشتى كنيد وبعد فرخنده را براى رمضان خواستگارى نمائيد. آنها به منزل مهدى رفته وخانواده اورا راضى كرده كه سرانجام ازدواج آنها صورت گرفت. فرخنده زنى سخت پوش وقوى ونيز مهربان بود، ودرخانه همسرش او را عزيز خانم نام نهاده بودند. آنهاحدود ٥٨ سال باهم زندگى مى نمايند ودر اين مدت داراى نوزده فرزندمى گردند كه متأسفانه هفت نفر از آنها در كودكى بعلت بيمارى فوت مى كنند، وهم اكنون شش پسر وشش دختر بنامهاى: اقدس، اختر، فرنگيس، مهرانگيز ، محمد، مهدى، باقر، اصغر، مهين، منيژه، على وحجت باقيمانده كه درقيد حياتند. رمضان در سن ٩٣ سالگى درسال ١٣٦٥هجرى شمسى بعلت بيمارى سرطان درگذشت. جالب توجه است كه تولد رمضان در ماه رمضان وفوت او نيز درماه رمضان بوده است.', NULL, 'Qazvin, Iran', '2026-08-27T07:56:09.237Z');
