INSERT INTO stories (id, title, body, date, place, created_at) VALUES ('786207e7-997e-41b1-982d-dd97f6d52762', 'Fatemeh Darabi, fifth generation', 'فاطمه خانم دارابى (نسل پنجم) فاطمه خانم تقريباً در سال ١٢٦٨ هجرى شمسى در قزوين متولد گرديد، او بسيار متين، باوقار، وزيباو نيز داراى قامتى بلند بوده است. خانه دارى، بچه دارى خوب وعلاقه مندى به فاميل از محاسن او بشمار مى رفت. همسرش آقاى حاج رمضان جابريان نيز مردى مسلمان، پاكدامن، ساكت وگوشه گير بود، شغل او بارفروشى وامانت فروشى در بازار قزوين بود. فاطمه خانم مانند مادرش ( سلمه) داراى چهار فرزند پسر ويك دختر گرديد، نام آنها، اسداله، سيف اله، فرج اله، عزت اله وكبرى مى باشد.اورا در منزل همسرش ميرزا باجى نامداده بودند. فاطمه خانم در ميان سالى از دنيا رفت وغم بسيار بزرگى رادر دل فرزندان، برادران وهمسر خودبوجود آورد. ( از فاميل محترم جابريان ويا كسانيكه اطلاعات بيشترى از فاطمه خانم دارند تقاضا ميشود آن اطلاعات را براى اينجانب محمد دارابى ويا آقاى دكتر ناصر دارابيها ارسال نمايند تا با نام خودشان ثبت گردد) متشكرم.', NULL, 'Qazvin, Iran', '2026-08-27T07:56:09.237Z');
