INSERT INTO stories (id, title, body, date, place, created_at) VALUES ('933b80ba-c87d-48c3-ac39-6f61d4dd00b7', 'Ghassem and Asadollah, the first in the family to read and write', 'قاسم واسداله اولين باسواد فاميل شراكت محمد زهتاب وپسران ونوه اش كم كم رونق گرفت رمضان دارابى كه بعلت مسافرت هاى زياد وارتباط باتجار مختلف از وضعيت اجتماعى وقدرت بيان بيشترى برخوردار شده بود اقدام به ارسال روده براى تاجر جديدى كه در تبريز علاوه بر حاج رضا توبا به سرت روده اشتغال داشت مى نمايد، آن تاجر كه آلمانى بوده مسيو كاس نام داشت، او داراى يك تجارتخانه بزرگ، يك كارخانه وتعداد زيادى پرسنل بود، چون روده اى كه از قزوين رفته بسيار خوب بوده، تلگرافى از تبريز به شركت آنها مخابره ونماينده اى براى عقد قرارداد دعوت مى نمايد. لذا رمضان دارابى از جانب شركت براى اين مأموريت تعين وبه تبريز اعزام مى گردد. در آن زمان اكثر مردم كشور ونيز برادران دارابى واسداله جابريان بعلت كمبود مدرسه ونيزنداشتن فرهنگ آموزش درخانواده وهمچنين داشتن كار زياد،بى سواد بودند، وحتى براى امضاء از مهر وانگشت استفاده مى كردند. رمضان دارابى هم بى سواد بود ولى چون داراى قدرت خوبى در ارائه مطالب وهمچنين آشنائى بيشتر با روابط اجتمائى آنروز داشت جهت عقد قرار داد انتخاب ورهسپار تبريز گرديد. او به آدرس داده شده مراجعه واز نگهبان ورودى سراغ مسيو كاس راگرفت، نگهبان به او گفت وارد آن ساختمان بشويد وبه اطاق شماره هفت مراجعه كنيد، او وارد ساختمان شد، چون سواد نداشت نمى دانست كه شماره ٧ كدام است، در راهرو نيز كسى نبود كه او سئوال كند، از نداشتن سواد از خود خجالت كشيدوفهميد كه سواد بسيار خوب است، كارى نمى توانست بكند، فقط مى دانست كه عدد يك مثل شاخ بز دراز است، اولين در سمت چپ را ديد كه عدد بالاى آن دراز است، باخود گفت حتماً اين يك ودر روبرو نيز حتماً دووآن يكى سه وخلاصه عدد ٧ راپيداكرد، وارد اطاق شدو خود را به منشى معرفى كرد، وسپس بامسيو كاس آشنا شده وحدود سه ساعت بااو، مترجم ومشاور حقوقيش گفتگو كرد. آنگاه با آن سه نفر به محضر رفتند، در محضر ودرحضور سردفتر نيز حدود دو ساعت با مسيو كاس ووكيلش چانه زدندوتمام مواد حاصل در قرارداد را با استفاده از خواندن وكيل كنترل كرد، قرار داد ثبت دفتر گرديد وهنگام امضاء، رمضان دارابى مهر خود را آماده كرد كه زير قرارداد وارد نمايد، ناگهان سر دفتر ناراحت شد وفرياد برآورد، آقا شما چرا امضاء نمى كنيد؟ رمضان دارابى گفت كه سواد ندارم، نمى دانم امضاء كنم بااعلام اين موضوع ناگهان مسيو كاس، وكيلش وهمچنين سر دفتر حيرت كرده ودرمورد او تفكر ديگرى دور از واقعيت نمودند. سردفتر مجدداً فرياد زد من كه باور نمى كنم، رمضان دارابى كه روز قبل از سفرش به تبريز در قزوين قرارداد ديگرى منعقد كرده بود ودر آن موقع هنوز آن قرارداد درجيبش بود، آنرا بيرون آورد وبه سر دفتر گفت ببينيد در اين قرارداد هم مهرزده ام، سردفتر كه به او چپ چپ نگاه مى كردبا ديدن آن قرارداد ناگهان از جا برخواست واورا بغل كرد وصورت او را چندين بار بوسيد وگفت اين كارت هم نشانگر هوش زيادت است ومن در مورد تو اشتباه فكر كردم مراببخشيد، چون باآن ايرادهائى كه دو ساعت از وكيل مسيو كاس گرفتى، وقرارداد رابه نفع خودت تمام كردى من فكر كردم از سواد حقوقى بسيار بالائى برخوردارى، وقتى گفتى سواد ندارم، اصلاً باور نكردم واگر قسم هم مى خوردى باز باور نمى كردم وباز با نشان دادن اين قرار دادكه در محضر يك قزوين منعقد گرديده وامضاء سر دفتر آن آقاى حاج ميرزا اسحاق راكه برايم خيلى محترم است ديدم، فقط توانستم باور كنم كه واقعاً تو سواد ندارى، ومن واقعاً شگفت زده شدم، آنگاه مجدداً اورا بوسيد وگفت پسرم چرا سواد ندارى همين حالا ميتوانى به مدرسه بروى، واقعاً حيف است. پس از امضاء قرارداد وهنگام مراجعت، رمضان كه از نداشتن سواد رنج مى برد در اتوبوس به فكر حرفهاى سر دفتر افتاد وهمچنان در انديشه فرورفت وبا خود گفت من كه كارم زياد است خوب است به فكر بچه ها باشم تااينكه به قزوين رسيد، در اولين فرصت قاسم واسداله را به مدرسه شبانه بردوآنها راتشويق. به درس خواندن نمود، آنها هم كه سنشان از سن مدرسه گذشته بود با فشار كارى روزانه، عصرها به كلاس درس رفتند تااينكه سوادى نسبتاً خوب پيدا كردند. پس از آنها سيف اله وفرج اله جابريان، غلامرضا واقدس دارابى وبه ترتيب تمام بچه ها بموقع به مدرسه رفته وبا سواد شدند وامروزه باعث افتخار است كه در فاميل تعداد زيادى پروفسور، دكتر، مهندس، فوق ليسانس وغيره ديده مى شوند.', NULL, NULL, '2026-08-27T07:56:09.237Z');
