INSERT INTO stories (id, title, body, date, place, created_at) VALUES ('bede1e68-3073-49ae-98e0-7c0619d27e4c', 'The two Ramazans'' journey to Qom', 'مسافرت رمضانها به قم درمورد سر شاخه ها ومنسوبين آنها اطلاعاتى وجود داردكه بشرح زير براى فاميل عزيز مى نويسم: روزى رمضان جابريان قصدداشت براى زيارت حضرت معصومه به قم مسافرت نمايد،در آن زمان رمضان دارابى دوازده ساله بود. او نيز علاقمند به زيارت بود، ولذا از پدرومادرش خواست كه به او هم اجازه مسافرت با رمضان جابريان ( شوهر خواهرش) را بدهند، آنها نيز موافقت كرده وبه آقاى رمضان جابريان سفارش لازم را كردند كه مواظب رمضان كوچك باشد.رمضان جابريان كه خواسته آنها را قبول كرده بود براى حمل بارهاى خود يك الاغ خريد وبارهاى مسافرتش راروى آن قرار داده ودست برادر همسرش راگرفت وپس از خداحافظى راهى مسافرت گرديدند. دوشب درراه، بودند،رمضان كوچك گاهى سوار الاغ شده وگاهى نيز پياده مى رفت تااينكه غروب روز سوم وارد قم شده ويكسر به حرم حضرت معصومه رفتند، در آنجا پس از وضو گرفتن وزيارت كردن، مشغول بجاى آوردن نماز جماعت گرديدند، رمضان كوچك كه سه روز خستگى راه را دربدن داشته ودركنارى ترين نفر يكى از صف ها قرار داشت هنگام سجده روى مهر بخواب رفت وپرده اى كه در كنارش قرار داشت روى او افتاده واو بدون اينكه خود بفهمد در پشت پرده پنهان شد، پس از نماز رمضان جابريان او رانديدوبدنبال او گشت واز اينكه اورا گُم كرده بود بسيار ناراحت بوده ونمى دانست كه به والدين او چه بگويد،او تمام صحن حرم، خيابانها وكوچه هاى اطراف را گشت وسر انجام به كلانترى رفته وگم شدن رمضان كوچك رااطلاع داد، وخلاصه تاصبح نتوانست بخوابد. صبح روز بعد مجدداً براى نماز جماعت به حرم رفت ومشغول خواندن نماز شد، رمضان كوچك كه در پشت پرده همچنان خوابيده بود، هنگام نماز صبح از خواب بيدار شده وفكر كرد كه دروسط نماز شب قرار دارد، پس از اتمام نماز، رمضان جابريان را پيدا كردونزد اورفت، رمضان جابريان كه او را ديد بسيار خوشحال شده وپرسيد از ديشب كجا بودى؟ او كه از پرسش حاج رمضان متعجب گرديده بود گفت چرا از ديشب؟ امشب ما آمديم، ونماز خوانديم وحالا هم نماز تمام شده، رمضان جابريان وقتى محل خواب اورا بررسى كرد، فهميد كه درپشت پرده پنهان شده وتا صبح خوابيده است، وباخوشحالى با او رفتار كرد، آنها پس از چند روز گردش وزيارت به قزوين برگشتند.', NULL, 'Qom, Iran', '2026-08-27T07:56:09.237Z');
