INSERT INTO stories (id, title, body, date, place, created_at) VALUES ('025f13a4-ec84-4bf4-8964-0fd7f8190b60', 'A day''s hunting', 'يك روز شكار دريك روز جمعه در زمستان در شهر قزوين، حسين زهتاب (دارابى) ودونفر از دوستانش بهمراه رمضان دارابى كه حدود ١٣ سال داشت براى شكار كبك به كوهستان هاى شمال قزوين رفتند، روى زمين حدود ٢٠ سانتيمتر برف نشسته ولى هوا آفتابى وخوب بود وآنها از راه رفتن روى برفها لذت مى بردند، ناگهان پسر بچه اى راديدند كه درحال گريه كردن ودويدن بطرف شهر مى باشد، حسين به پسرك گفت چه شده، كجا مى روى؟ پسر گفت كه برادرم در چاه افتاد، حسين وهمراهان بلادرنگ به طرف چاهى كه او نشان مى داد دويدند و ديدند كه سنگهاى اطراف چاه داخل چاه ريخته، پسرك گفت برادرم زير اين سنگها است، حسين وهمراهان بسختى سنگهارا برداشته وبرادر آن پسر راكه هنوز زنده بود نجات دادند، پس از اينكه مقدارى غذا وميوه به او دادند، سئوال كردند چرا داخل چاه افتادى؟ او گفت كه من بيكار هستم، درآمدى ندارم، براى گرفتن وخوردن كبوتر چاهى بداخل چاه رفتم كه سنگها رويم ريخت. گروه شكار به آن پسر وبرادرش مقدارى پول داده ومجدداً براه شكار خود ادامه دادند. پس ازنيم ساعت پير مردى راديدند كه نزديك كلبه اى نشسته و گريه مى كند، از اوپرسيدند چه اتفاقى افتاده؟ او گفت من جايى براى زندگى ندارم ودر اين كلبه زندگى مى كنم وهميشه نيز از آب اين چاه استفاده مى كنم، امروز دلوى كه باآن از چاه آب مى كشيدم به چاه افتادومن نمى دانم آنرا بيرون بياورم، حسين به يكى از همراهان گفت مى توانى بداخل چاه بروى؟ او گفت آرى، او به چاه رفت وپس از مدتى دلو را از چاه بيرون آورد، پير مرد خوشحال شد وحسين نيز مقدارى پول به او دادومجدداً گروه شكار رهسپار بيابان گرديدند. تقريباً نزديك ظهر بود كه ناگهان صداى دعوا وزدو خورد از داخل اطاقكى كه در بيابان قرار داشت شنيده شد، آنها نزديكتر رفته پسرك دست وپا بسته اى را در وسط اطاق ديدند، ونيز ديدند كه چهار نفر با هم زدوخورد مى كنند، آنها قصد داشتند به پسرك تجاوز نمايند وهر كدام مى خواستند اول شروع كنند حتى براى هم چاقو نيز كشيده بودند. حسين زهتاب ناگهان بداخل اطاق حمله كردو با آوردن ضربات چوب به روى دستان آنها چاقوهايشان را به زمين انداخت، آنها فرار كردند، حسين دست وپاى جوانك را باز وسؤال كرد چرا باآنها آمدى؟ او گفت يكى از آنها با من دوست است، او مرا گول زد وبه اينجا آورد وخوب شد كه شما مرا نجات داديد. آن جوانك نيز همراه گروه شكاربه راه افتاد وتا نزديك غروب با آن گروه بود ودر آخر باآنها به شهر برگشت. تقريباً پس از ١٢ سال حسين زهتاب كه براى فروش زه به شهر ساوه رفته بود درآنجا باشخص معروفى بنام صادق ساوه اى آشنا شده ووارد يك معامله تجارى گرديد كه در اين معامله آن شخص مبلغ صد تومان پول حسين را بالا كشيده وبه او نداد، حسين مدركى نداشت كه بتواند آنرا بگيرد ناچار به قزوين برگشت ، رمضان دارابى كه بزرگ شده وجوانى خوش فكر بود وقتى از ماجرا باخبر شد، مى گويد من به ساوه رفته وصد تومان را زنده مى كنم، لذا براى اين منظور نقشه اى طرح كرده وابتدا نزد ميكاييل خان ارمنى كه يكى از تجار معروف كشور بوده ودرقزوين اقامت داشته مى رود، او قبلاً يكى از كاركنان ميكاييل خان بوده، ميكاييل خان كه او را به خوشنامى وصداقت مى شناخته از اواستقبال كرده وعلاقمند كمك به او مى گردد. او به ميكاييل مى گويد در چند روز آينده براتى عهده شما از ساوه صادر وتوسط بانك ملى ارسال مى نمايم، اگر مهرم را در زير برات افقى زدم باپرداخت برات موافقت نمائيد واگر عمودى زدم آنرا نكول وبرگردانيد. ميكائيل خان قبول نمود، رمضان دارابى به ساوه رفته وصادق ساوه اى راپيدا مى نمايد ودر آنجا بنام دارابى وارد معامله مى گردد. صادق ساوه اى كه آنها را بنام زهتاب مى شناخت،نمى فهمد كه او برادر حسين است، او معاملاتى انجام داده وفرشهاى زيادى خريدارى كرده، وبرات را با مهر عمودى صادر مى نمايد، برات در قزوين به ميكائيل خان ابلاغ مى گردد، او آنرا نكول كرده وعودت مى دهد، صادق ساوه اى كه بسيارناراحت شده بود از دست رمضان دارابى به دادگسترى ساوه شكايت مى نمايد، احضاريه اى در مسافرخانه به رمضان دارابى ابلاغ مى گردد، رمضان دارابى صبح زود و قبل از ساعت دعوت شده به دادگسترى مى رود تا شايد بتواند راهى براى اين منظود بيابد، در راهرو دادگسترى ناگهان شخصى رودرروى او قرار مى گيرد، هردو نفر احساس مى كنند هم ديگر را مى شناسند، آن مردمى گويد ببخشيد آقا شما قزوينى هستيد؟ رمضان مى گويد بله، آن شخص مى گويد شما برادر حسين زهتاب هستيد؟ رمضان مى گويد بله من برادر حسين دارابى هستم وشما؟ اوميگويد من همان هستم كه در دوازده سال پيش توسط حسين از دست آن چهار نفر نجات داده شدم وحالا رئيس دادگسترى مى باشم، شما اينجا چه مى كنيد، رمضان دارابى ماجرا رابطور كامل براى او تعريف مى نمايد، آن شخص روى سر برگ دادگسترى نامه اى از قول دادگسترى مركز براى دادگسترى ساوه نوشته وآنرا داخل پاكت گذاشته وبه رمضان دارابى داده ومى گويد درمقا بل صادق ساوه اى اين نامه رابه من بده، در ساعت مقرر دادگاه تشكيل مى گردد، صادق ساوه اى كه به مناسبت دوستى با رئيس دادگسترى از او خواسته بوده دادگاه را خودش اداره نمايد در كنار صندلى رئيس مى نشيند، رئيس از رمضان دارابى مى پرسد آيا شماپول اين آقارا برداشته وكلاه بردارى كرده ايد؟ رمضان مى گويد بله ولى دليل دارم، سپس نامه رابه رئيس مى دهد، رئيس درحاليكه نامه را مى خواند آنرا طورى مى گيرد كه صادق هم بتواند بخواند، رمضان ناگهان مى بيند كه رنگ صورت صادق تغيير كرد، زيرا در نامه نوشته بود صادق ساوه اى كلاه بردار است فوراً او رادست بسته به تهران اعزام نمائيد، رئيس آهسته به صادق مى گويدأيا شما پول برادر اين آقارا برداشته ايد؟ اگر چنين است بگو تامن پا در ميانى كرده ونگذارم شمارا به تهران ببرند صادق مى گويد خودت يك كارى بكن، رئيس به رمضان مى گويد اگر صد تومان شما وبهره آنرا بدهد شما از شكايت خود صرفنظر مى كنيد؟ رمضان مى گويد بله، آنگاه رئيس بدهى صادق را از بدهى رمضان كسر كرده وبه رمضان مى گويد بقيه را چطور مى دهى؟ رمضان مى گويد برات بانك ملى به قزوين، دادگاه تمام شده ورمضان برات را صادر و اين بار با مهر افقى ممهور وارسال مى نمايد، در قزوين نيز ميكائيل خان قبول كرده ورمضان دارابى با اجناس خريدارى شده به قزوين برمى گردد. اين ثمره نكوكارى حسين بوده كه آن جوان را نجات داده بوده است.', NULL, 'Qazvin, Iran', '2026-08-27T07:56:09.237Z');
