INSERT INTO stories (id, title, body, date, place, created_at) VALUES ('7223daa3-2f7b-40f6-8c2e-5a4b0ac5813e', 'The customs duty on gut', 'گمرك روده پس از جنگ دوم جهانى بازارهاى تجارى در ايران كم كم رونق گرفت، شراكت محمد زهتاب وفرزندانش بخوبى پيش رفته وآنها كار روده را باموفقيت انجام مى دادند. روزى آقاى اسماعيل مسعودى ( برادر همسر قاسم دارابى)، تكه روزنامه اى را كه دردست داشت واز سبزى فروشى بابت خريد سبزى گرفته بود، به رمضان دارابى مراجعه نموده و مى گويد براى روده گمرك تعين كرده اند، او كه روزنامه باطله را در حضور رمضان مى خواند، مشخص شد كه از سه ماه قبل يك آگهى در روزنامه چاپ ودر مورد گمرك روده تاريخى تعين كرده بودند كه آنروز دو روز به آن تاريخ باقى مانده بود.از آن روز ببعد روده اى كه بابت آن گمرك نداده بودند قاچاق محسوب مى گرديد. چون در فاميل كسى اهل خواندن روزنامه نبود آنها كاملاً بى اطلاع بودند. بهر صورت رمضان دارابى از آقاى مسعودى تشكر كرده وپس از آن به فكر فرو رفته تا راه حلى براى اين موضوع پيدانمايد. چند ساعتى بررسى وتفكر كرده وسرانجام راه آن را پيدا مى نمايد، لذا بلافاصله مقدار زيادى از ضايعات لاشه هاى گاو وگوسفند كه در كشتارگاه موجود بودومى خواستند آنها را دور بريزند را داخل تعداد زيادى بشگه قرار داده وبه اداره گمرك مراجعه وتقاضانامه پلمب كردن روده را، تحويل مى دهد، نماينده اى از گمرك به محل كارخانه آنها آمده وچون با روده آشنائى نداشت آن ضايعات رابجاى روده پلمب مى كند. از تاريخ تعين شده ببعد ناگهان قيمت روده بدون پلمب حدود هفتاد درصد كاهش وارزش روده پلمب شده نيز افزايش مى يابد. آنها شروع به خريد روده پلمب نشده مى كنند كه خيلى ارزان بود. روزى كه مقدار زيادى خريد كرده ومى خواستند به تبريز ارسال نمايند، رمضان دارابى به نماينده اى كه قبلاً از گمرك آمده وبشگه هارا پلمب كرده بود مراجعه وبه او مى گويد متأسفانه آنروز كارگران اشتباهى بجاى رودهها، آشغال ها را در بشگه ريخته بودند وشماهم آنها را پلمب كرده ايد، لطفاً به كارخانه بيائيد و ببينيد، او به كارخانه مى آيد ويكى از پلمب هاراباز كرده ومى بيند كه درست مى گويد، خلاصه كل روده هارا بجاى آشغال ها گذاشته ومجدداً به تاريخ آنروز پلمب مى نمايد.وبابت آن كارمزد وپاداشى نيز مى گيرد. در اين معامله شركت روده را با هفتاد درصد زير قيمت خريده وبا صددرصد به فروش مى رساند، وسود خوبى عايدش مى شود. رمضان دارابى هميشه به فرزندان واطرافيانش مى گفت هر روزنامه ونوشته ويامطلبى كه ديديد، حتى اگر روى زمين هم افتاده بود آنرا برداشته وبخوانيد.', NULL, NULL, '2026-08-27T07:56:09.237Z');
