INSERT INTO change_log (id, actor_email, kind, summary, payload_json, created_at) VALUES ('f61cad56-c70a-479b-8a06-3f79c8b7c747', 'ramine@ramine.net', 'import_legacy_stories', 'Imported 8 Persian family histories from the legacy archive as stories.', '{"entries":["A historic marriage (1927) — 5829 chars, 5 people: Mohammad Zehtab Darabi, Hossein Zehtab Darabi, Ramazan Darabi, Ghassem Darabi, Asadollah Jaberian","Hossein Zehtab (Darabi), fifth generation — 2945 chars, 5 people: Hossein Zehtab Darabi, Ghassem Darabi, Ategheh Khanom, Mehdi Zehtab, Akram Darabi","Ramazan Darabi, fifth generation — 1694 chars, 4 people: Ramazan Darabi, Fatemeh Darabi, Mehdi Zehtab, Farrokhandeh","Fatemeh Darabi, fifth generation — 815 chars, 8 people: Haj Ramazan Jaberian, Fatemeh Darabi, Asadollah Jaberian, Seifollah Jaberian, Farajollah Jaberian, Ezatollah (Ahmad) Jaberian, Kobra Jaberian, Salmeh","Ghassem and Asadollah, the first in the family to read and write — 3650 chars, 6 people: Mohammad Zehtab Darabi, Ramazan Darabi, Ghassem Darabi, Asadollah Jaberian, Seifollah Jaberian, Farajollah Jaberian","The two Ramazans'' journey to Qom — 1879 chars, 2 people: Ramazan Darabi, Haj Ramazan Jaberian","A day''s hunting — 5297 chars, 2 people: Hossein Zehtab Darabi, Ramazan Darabi","The customs duty on gut — 2066 chars, 3 people: Mohammad Zehtab Darabi, Ramazan Darabi, Ghassem Darabi"]}', '2026-08-27T07:56:09.237Z');
